from decimal import Decimal


def totals_by_customer(orders):
    """Sum amounts of non-cancelled orders, grouped by customer ID.

    Orders whose ``status`` is ``"cancelled"`` are excluded. A missing
    ``status`` is treated as active. Amounts are converted with ``Decimal``
    and the returned mapping is ordered by customer ID.
    """
    totals = {}
    for order in orders:
        if order.get('status') == 'cancelled':
            continue
        customer_id = order['customer_id']
        amount = Decimal(str(order['amount']))
        totals[customer_id] = totals.get(customer_id, Decimal('0')) + amount
    return {customer_id: totals[customer_id] for customer_id in sorted(totals)}

