"""Channel notification dispatcher backed by a registry.

Channels register their handler with the ``@_register`` decorator; ``send``
looks the handler up by name. Unknown channels raise ``ValueError``.
"""

from typing import Callable

_CHANNELS: dict[str, Callable[[str], str]] = {}


def _register(name: str) -> Callable[[Callable[[str], str]], Callable[[str], str]]:
    """Register ``name`` as a channel and return the handler unchanged."""

    def decorator(handler: Callable[[str], str]) -> Callable[[str], str]:
        _CHANNELS[name] = handler
        return handler

    return decorator


